#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

static int parse_int(const char *text, int *result)
{
    char *end = NULL;
    long value;

    errno = 0;
    value = strtol(text, &end, 10);
    if (text == end || errno == ERANGE || value < INT_MIN || value > INT_MAX) {
        return 0;
    }
    while (*end != '\0' && isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0') {
        return 0;
    }
    *result = (int)value;
    return 1;
}

static int append_int(int **items, size_t *count, size_t *capacity, int value)
{
    if (*count == *capacity) {
        size_t new_capacity = (*capacity == 0U) ? 2U : *capacity * 2U;
        int *temporary;

        if (new_capacity < *capacity || new_capacity > SIZE_MAX / sizeof **items) {
            return 0;
        }
        temporary = realloc(*items, new_capacity * sizeof **items);
        if (temporary == NULL) {
            return 0;
        }
        *items = temporary;
        *capacity = new_capacity;
    }
    (*items)[*count] = value;
    ++(*count);
    return 1;
}

int main(void)
{
    const char *input[] = {" 42 ", "-7", "12x", "999999999999999999999999"};
    int *values = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    size_t i;

    for (i = 0U; i < sizeof input / sizeof input[0]; ++i) {
        int parsed;
        if (parse_int(input[i], &parsed)) {
            if (!append_int(&values, &count, &capacity, parsed)) {
                fputs("Could not grow the array.\n", stderr);
                free(values);
                return EXIT_FAILURE;
            }
            printf("Accepted: %d\n", parsed);
        } else {
            printf("Rejected: %s\n", input[i]);
        }
    }

    printf("Stored %zu value(s).\n", count);
    free(values);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
    const char *label;
} Item;

static int compare_item_id(const void *left, const void *right)
{
    const Item *a = left;
    const Item *b = right;

    return (a->id > b->id) - (a->id < b->id);
}

int main(void)
{
    Item items[] = {{30, "Gamma"}, {10, "Alpha"}, {20, "Beta"}};
    const size_t count = sizeof items / sizeof items[0];
    Item key = {20, NULL};
    Item *found;
    size_t i;

    qsort(items, count, sizeof items[0], compare_item_id);
    for (i = 0U; i < count; ++i) {
        printf("%d: %s\n", items[i].id, items[i].label);
    }

    found = bsearch(&key, items, count, sizeof items[0], compare_item_id);
    if (found != NULL) {
        printf("Found ID %d (%s).\n", found->id, found->label);
    } else {
        puts("ID not found.");
    }
    return EXIT_SUCCESS;
}
